import { useState, useRef, useEffect } from 'react';
import { Camera, Image as ImageIcon, Loader2, Sparkles, Globe, KeyRound, ChevronLeft, ChevronRight, Download } from 'lucide-react';
import { Flow } from 'flow-sdk';
import { analyzeSpace, generate360, enhanceCleanShot } from './services/ai';
import { PanoramaViewer, PanoramaViewerRef } from './components/PanoramaViewer';

interface Shot {
  id: string;
  base64: string | null;
  isLoading: boolean;
  label: string;
}

function MiniMapOverlay({ yaw, pitch, fov }: { yaw: number, pitch: number, fov: number }) {
  const [vfDim, setVfDim] = useState<{ width: number, height: number, canvasHeight: number } | null>(null);

  useEffect(() => {
    const updateDimensions = () => {
      const vf = document.getElementById('viewfinder');
      const container = document.getElementById('panorama-container');
      if (vf && container) {
        setVfDim({
          width: vf.clientWidth,
          height: vf.clientHeight,
          canvasHeight: container.clientHeight,
        });
      }
    };

    updateDimensions();
    window.addEventListener('resize', updateDimensions);
    return () => window.removeEventListener('resize', updateDimensions);
  }, []);

  // Base canvas vertical FOV in radians
  const vFovRad = (fov * Math.PI) / 180;

  // Calculate viewfinder vertical FOV based on screen proportion
  let vfVFovRad = vFovRad;
  let vfHFovRad = 2 * Math.atan(Math.tan(vfVFovRad / 2) * (16 / 9));

  if (vfDim) {
    // Math to project window's fov down to viewfinder's pixel height
    const d = (vfDim.canvasHeight / 2) / Math.tan(vFovRad / 2);
    vfVFovRad = 2 * Math.atan((vfDim.height / 2) / d);
    // Viewfinder horizontal FOV is based on its actual width vs distance
    vfHFovRad = 2 * Math.atan((vfDim.width / 2) / d);
  }

  const vfVFovDeg = (vfVFovRad * 180) / Math.PI;
  const vfHFovDeg = (vfHFovRad * 180) / Math.PI;

  const widthPercent = (vfHFovDeg / 360) * 100;
  const heightPercent = (vfVFovDeg / 180) * 100;

  // OrbitControls azimuthalAngle goes from -PI to PI
  // With scale={[-1, 1, 1]}, looking at Z = -500 corresponds to u=0.75
  let x = 0.75 - yaw / (2 * Math.PI);
  while (x < 0) x += 1;
  while (x > 1) x -= 1;

  // OrbitControls polarAngle (pitch) goes from 0 to PI
  // 0 is looking straight down (south pole -> bottom of image -> 100%)
  // PI is looking straight up (north pole -> top of image -> 0%)
  const y = 1 - pitch / Math.PI;

  const left = x * 100 - widthPercent / 2;
  const top = y * 100 - heightPercent / 2;

  return (
    <>
      {/* Primary Highlight */}
      <div 
        className="absolute border border-white/80 bg-white/10 shadow-[0_0_10px_rgba(0,0,0,0.5)]"
        style={{
          left: `${left}%`,
          top: `${top}%`,
          width: `${widthPercent}%`,
          height: `${heightPercent}%`,
          boxShadow: '0 0 0 999px rgba(0,0,0,0.4)',
        }}
      />
      {/* Seamless Wrap-around (Left Edge) */}
      {left < 0 && (
        <div 
          className="absolute border border-white/80 bg-white/10 shadow-[0_0_10px_rgba(0,0,0,0.5)]"
          style={{
            left: `${left + 100}%`,
            top: `${top}%`,
            width: `${widthPercent}%`,
            height: `${heightPercent}%`,
          }}
        />
      )}
      {/* Seamless Wrap-around (Right Edge) */}
      {left + widthPercent > 100 && (
        <div 
          className="absolute border border-white/80 bg-white/10 shadow-[0_0_10px_rgba(0,0,0,0.5)]"
          style={{
            left: `${left - 100}%`,
            top: `${top}%`,
            width: `${widthPercent}%`,
            height: `${heightPercent}%`,
          }}
        />
      )}
    </>
  );
}

export default function App() {
  const [hasApiKey, setHasApiKey] = useState<boolean>(true);
  const [currentScreen, setCurrentScreen] = useState<'home' | 'viewer'>('home');

  // Home States
  const [referenceImage, setReferenceImage] = useState<string | null>(null);
  const [brief, setBrief] = useState('');
  const [isGenerating360, setIsGenerating360] = useState(false);

  // Viewer States
  const [panoramaUrl, setPanoramaUrl] = useState<string | null>(null);
  const [isRenderingShot, setIsRenderingShot] = useState(false);
  const [numEnhancements, setNumEnhancements] = useState(1);
  const viewerRef = useRef<PanoramaViewerRef>(null);
  const [savedShots, setSavedShots] = useState<Shot[]>([]);
  const [rawViewportShot, setRawViewportShot] = useState<string | null>(null);
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [viewState, setViewState] = useState({ yaw: 0, pitch: Math.PI / 2, fov: 70 });

  useEffect(() => {
    // Inject Tailwind and base styles
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    document.head.appendChild(script);

    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=Inter:wght@200;300;400;500;600&family=JetBrains+Mono:wght@400;500&display=swap');
      html, body, #root { 
        height: 100%; 
        margin: 0; 
        padding: 0; 
        background: #0e0e0e; 
        color: white; 
        font-family: 'Inter', sans-serif;
      }
      .scrollbar-hide::-webkit-scrollbar { display: none; }
      .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
    `;
    document.head.appendChild(style);

    const checkApiKey = async () => {
      if ((window as any).aistudio && (window as any).aistudio.hasSelectedApiKey) {
        const hasKey = await (window as any).aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      }
    };
    checkApiKey();
  }, []);

  const handleSelectKey = async () => {
    if ((window as any).aistudio && (window as any).aistudio.openSelectKey) {
      await (window as any).aistudio.openSelectKey();
      setHasApiKey(true);
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (lightboxIndex !== null) {
        if (e.key === 'ArrowLeft') {
          setLightboxIndex(prev => prev !== null && prev > 0 ? prev - 1 : prev);
        } else if (e.key === 'ArrowRight') {
          setLightboxIndex(prev => prev !== null && prev < savedShots.length - 1 ? prev + 1 : prev);
        } else if (e.key === 'Escape') {
          setLightboxIndex(null);
        }
      } else if (lightboxImage !== null && e.key === 'Escape') {
        setLightboxImage(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [lightboxIndex, lightboxImage, savedShots.length]);

  const handleFileUpload = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        setReferenceImage(`data:${media.mimeType};base64,${media.base64}`);
      }
    } catch (e) {
      console.error("Failed to select media", e);
    }
  };

  const handleUpload360 = async () => {
    try {
      const media = await Flow.media.select({ filter: 'image' });
      if (media) {
        setPanoramaUrl(`data:${media.mimeType};base64,${media.base64}`);
        setCurrentScreen('viewer');
      }
    } catch (e) {
      console.error("Failed to select media", e);
    }
  };

  const handleGenerateFromReference = async () => {
    if (!referenceImage) return;
    setIsGenerating360(true);
    try {
      const context = await analyzeSpace(referenceImage, brief);
      const imgUrl = await generate360(context, referenceImage);
      setPanoramaUrl(imgUrl);
      setCurrentScreen('viewer');
    } catch (e: any) {
      console.error(e);
      if (e.message?.includes('Requested entity was not found')) {
        setHasApiKey(false);
      } else {
        alert("Failed to generate 360 environment. See console.");
      }
    } finally {
      setIsGenerating360(false);
    }
  };

  const handleRenderShot = async () => {
    if (!viewerRef.current) return;
    setIsRenderingShot(true);
    try {
      const canvasBase64 = viewerRef.current.capture();
      if (!canvasBase64) throw new Error("Could not capture canvas");

      setRawViewportShot(canvasBase64);

      const allPrompts = [
        { label: "Move Backward", instruction: "Move the camera a bit backwards and retake the shot." },
        { label: "Move Forward", instruction: "Move the camera a bit forward and retake the shot." },
        { label: "Move Left 2ft", instruction: "Move the camera 2 feet to the left and retake the shot." },
        { label: "Move Right 2ft", instruction: "Move the camera 2 feet to the right and retake the shot." },
      ];

      const prompts = [...allPrompts].sort(() => 0.5 - Math.random()).slice(0, numEnhancements);

      const newShots = prompts.map(p => ({
        id: crypto.randomUUID(),
        base64: null,
        isLoading: true,
        label: p.label
      }));

      setSavedShots(prev => [...newShots, ...prev]);

      newShots.forEach(async (shot, idx) => {
        try {
          const enhancedBase64 = await enhanceCleanShot(canvasBase64, prompts[idx].instruction);
          setSavedShots(prev => prev.map(s => s.id === shot.id ? { ...s, base64: enhancedBase64, isLoading: false } : s));
        } catch (e: any) {
          console.error(e);
          if (e.message?.includes('Requested entity was not found')) {
            setHasApiKey(false);
          }
          setSavedShots(prev => prev.map(s => s.id === shot.id ? { ...s, isLoading: false } : s));
        }
      });
    } catch (e: any) {
      console.error(e);
      alert("Failed to render clean shot. See console.");
    } finally {
      setIsRenderingShot(false);
    }
  };

  const downloadImage = async (url: string, index: number) => {
    const mimeTypeMatch = url.match(/^data:(image\/[a-zA-Z]+);base64,/);
    const mimeType = mimeTypeMatch ? mimeTypeMatch[1] : "image/jpeg";
    const base64 = url.replace(/^data:image\/[a-zA-Z]+;base64,/, "");

    await Flow.download({
      base64,
      mimeType,
      filename: `scouter_shot_${index + 1}.jpg`
    });
  };

  const handleBackToHome = () => {
    if (panoramaUrl) {
      setShowExitConfirm(true);
    } else {
      confirmBackToHome();
    }
  };

  const confirmBackToHome = () => {
    setShowExitConfirm(false);
    setCurrentScreen('home');
    setPanoramaUrl(null);
    setReferenceImage(null);
    setBrief('');
    setSavedShots([]);
    setRawViewportShot(null);
    setLightboxImage(null);
    setLightboxIndex(null);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop360 = (e: React.DragEvent) => {
    e.preventDefault();
    const file = e.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPanoramaUrl(reader.result as string);
        setCurrentScreen('viewer');
      };
      reader.readAsDataURL(file);
    }
  };

  if (!hasApiKey) {
    return (
       <div className="flex flex-col h-screen w-full items-center justify-center bg-[#111] text-white p-6 overflow-y-auto">
         <div className="flex flex-col items-center justify-center w-full max-w-[400px] bg-[#111] p-8 border border-[#222]">
           <div className="w-16 h-16 border border-[#333] text-[#666] flex items-center justify-center mb-8">
             <KeyRound className="w-6 h-6" />
           </div>
           <h2 className="text-xl font-normal text-white tracking-wide mb-4 text-center">API Key Required</h2>
           <p className="text-[11px] text-[#666] text-center uppercase tracking-widest leading-relaxed mb-8">
             Please attach a project with billing enabled for the Nano Banana model.
             <br/><br/>
             <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noreferrer" className="text-[#aaa] hover:text-white underline">View Billing Documentation</a>
           </p>
           <button 
             onClick={handleSelectKey}
             className="w-full bg-transparent border border-white hover:bg-white text-white hover:text-black py-4 text-[10px] uppercase tracking-[0.15em] font-medium transition-colors"
           >
             Select API Key
           </button>
         </div>
       </div>
    );
  }

  return (
    <div className="bg-[#111] text-white h-screen w-screen overflow-hidden relative selection:bg-[#333]">
      {currentScreen === 'home' && (
        <div className="absolute inset-0 w-full h-full flex flex-col items-center justify-center z-10 opacity-100 bg-[#111]">
          <div className="relative z-10 flex flex-col items-center w-full max-w-5xl px-8">
            <div className="text-center md:mb-10 mb-6 mt-6 md:mt-0">
              <div className="flex items-center justify-center gap-2 text-[2.2rem] font-light tracking-tight mb-2">
                SCOUT<span className="text-[#666] font-light">360</span>
              </div>
              <p className="text-[#aaa] text-sm max-w-md mx-auto font-light leading-relaxed">
                Drop an existing equirectangular image to start scouting, or upload a reference image to generate a 360° environment.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 w-full border border-[#222] md:divide-x divide-y md:divide-y-0 divide-[#222] bg-[#111]">
              <div 
                className="p-8 md:p-10 flex flex-col group relative overflow-hidden"
                onDragOver={onDragOver}
                onDrop={onDrop360}
              >
                <div className="flex items-center gap-4 mb-6">
                  <div className="w-10 h-10 border border-[#333] flex items-center justify-center text-[#aaa]">
                    <Globe className="w-4 h-4" />
                  </div>
                  <h2 className="text-xl font-normal text-white tracking-wide">Upload Existing Panorama</h2>
                </div>
                <div 
                  onClick={handleUpload360}
                  className="flex-1 border border-dashed border-[#333] flex flex-col items-center justify-center gap-5 hover:border-[#666] transition-colors cursor-pointer group/drop min-h-[180px]"
                >
                  <div className="w-14 h-14 border border-[#333] flex items-center justify-center text-[#666] group-hover/drop:text-[#aaa] group-hover/drop:border-[#666] transition-colors">
                    <Globe className="w-6 h-6" />
                  </div>
                  <div className="text-center max-w-[240px]">
                    <p className="text-[11px] font-normal text-[#eee] uppercase tracking-[0.1em] mb-2">Upload Equirectangular</p>
                    <p className="text-[9px] text-[#666] uppercase tracking-widest leading-relaxed">Preferred aspect ratio is 2:1</p>
                  </div>
                </div>
              </div>

              <div className="p-8 md:p-10 flex flex-col group relative overflow-hidden">
                <div className="flex items-center gap-4 mb-6">
                  <div className="w-10 h-10 border border-[#333] flex items-center justify-center text-[#aaa]">
                    <Sparkles className="w-4 h-4" />
                  </div>
                  <h2 className="text-xl font-normal text-white tracking-wide">Generate 360°</h2>
                </div>
                <div className="space-y-6 flex-1 flex flex-col">
                  <div className="flex-1 flex flex-col">
                    <label className="block text-[10px] text-[#666] uppercase tracking-[0.1em] mb-3">Reference Image</label>
                    <div 
                      onClick={handleFileUpload}
                      className="flex-1 border border-dashed border-[#333] flex flex-col items-center justify-center gap-4 hover:border-[#666] transition-colors cursor-pointer group/drop overflow-hidden relative min-h-[140px]"
                    >
                      {referenceImage ? (
                        <>
                           <img src={referenceImage} alt="Reference" className="absolute inset-0 w-full h-full object-contain block opacity-80 group-hover/drop:scale-105 transition-transform duration-500" />
                           <div className="absolute inset-0 bg-black/40 opacity-0 group-hover/drop:opacity-100 transition-opacity flex items-center justify-center z-10">
                             <span className="text-white text-[10px] uppercase tracking-[0.1em] font-medium px-4 py-2 border border-white backdrop-blur-md">Change</span>
                           </div>
                        </>
                      ) : (
                        <>
                          <div className="text-[#444] group-hover/drop:text-[#aaa] transition-colors">
                            <ImageIcon className="w-6 h-6" />
                          </div>
                          <div className="text-center">
                            <p className="text-[11px] font-normal text-[#eee] uppercase tracking-[0.1em]">Upload Reference</p>                            
                          </div>
                        </>
                      )}
                    </div>
                  </div>
                  <div>                    
                    <div className="relative">
                      <input 
                        type="text" 
                        value={brief}
                        onChange={(e) => setBrief(e.target.value)}
                        placeholder="What would you like to see in this environment?" 
                        className="w-full bg-transparent border-0 border-b border-[#333] pr-0 py-2 text-sm text-white placeholder:text-[#444] focus:outline-none focus:border-white focus:ring-0 transition-colors tracking-wide" 
                      />
                    </div>
                  </div>
                </div>
                <button 
                  onClick={handleGenerateFromReference}
                  disabled={!referenceImage || isGenerating360}
                  className="mt-6 w-full bg-transparent border border-white hover:bg-white text-white hover:text-black disabled:border-[#222] disabled:text-[#444] disabled:hover:bg-transparent rounded-full py-3.5 text-[10px] font-medium tracking-[0.15em] uppercase transition-colors flex justify-center items-center gap-3"
                >
                  {isGenerating360 ? (
                    <>
                      <Loader2 className="w-4 h-4 animate-spin" />
                      Constructing Environment...
                    </>
                  ) : (
                    <>
                      <Sparkles className="w-4 h-4" />
                      Generate 360 Environment
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {currentScreen === 'viewer' && (
        <div className="absolute inset-0 w-full h-full flex z-10 bg-[#111] flex-col md:flex-row">
          <div id="panorama-container" className="flex-1 relative overflow-hidden flex flex-col order-1 md:order-none h-full">
            {/* Viewport */}
            {panoramaUrl ? (
                <PanoramaViewer 
                  ref={viewerRef} 
                  imageUrl={panoramaUrl} 
                  onViewChange={(yaw, pitch, fov) => setViewState({ yaw, pitch, fov })} 
                />
            ) : (
                <div className="absolute inset-0 flex items-center justify-center text-[#666]">
                    <Loader2 className="w-8 h-8 animate-spin" />
                </div>
            )}

            <div className="absolute inset-0 pointer-events-none select-none overflow-hidden h-full flex flex-col">
                <div className="absolute top-0 left-0 right-0 p-4 md:p-8 flex items-start z-10 pointer-events-none">
                  <button 
                    onClick={handleBackToHome}
                    className="pointer-events-auto flex items-center gap-3 bg-[#111] border border-[#222] rounded-none pl-4 pr-5 py-3 text-[10px] uppercase tracking-[0.1em] text-[#aaa] transition-colors hover:bg-[#222] group"
                  >
                    <ChevronLeft className="w-4 h-4 text-[#666] group-hover:text-white transition-colors" />
                    Back to Setup
                  </button>
                </div>

                {/* Viewfinder Grid */}
                <div className="absolute inset-y-24 inset-x-4 md:inset-y-32 md:inset-x-32 lg:inset-x-48 flex items-center justify-center pointer-events-none">
                    <div id="viewfinder" className="relative w-full max-w-[1280px] aspect-video border-[2px] border-white/60 shadow-[0_0_0_9999px_rgba(0,0,0,0.6)] bg-transparent">

                        {/* Capture Zone Label */}
                        <div className="absolute top-2 right-2 md:top-3 md:right-3 flex items-center gap-2 bg-black/60 backdrop-blur-sm border border-white/20 px-2 py-1 md:px-3 md:py-1.5 text-[8px] md:text-[9px] uppercase tracking-[0.1em] text-white/90 shadow-sm">
                          <div className="w-1 h-1 md:w-1.5 md:h-1.5 rounded-full bg-[#aaa]"></div>
                          <span>Capture Zone</span>
                        </div>
                        <div className="absolute inset-0 flex flex-col justify-evenly">
                            <div className="w-full h-[1px] bg-white/30"></div>
                            <div className="w-full h-[1px] bg-white/30"></div>
                        </div>
                        <div className="absolute inset-0 flex justify-evenly">
                            <div className="w-[1px] h-full bg-white/30"></div>
                            <div className="w-[1px] h-full bg-white/30"></div>
                        </div>

                        <div className="absolute -top-[2px] -left-[2px] w-4 md:w-6 h-4 md:h-6 border-t-[3px] border-l-[3px] border-white"></div>
                        <div className="absolute -top-[2px] -right-[2px] w-4 md:w-6 h-4 md:h-6 border-t-[3px] border-r-[3px] border-white"></div>
                        <div className="absolute -bottom-[2px] -left-[2px] w-4 md:w-6 h-4 md:h-6 border-b-[3px] border-l-[3px] border-white"></div>
                        <div className="absolute -bottom-[2px] -right-[2px] w-4 md:w-6 h-4 md:h-6 border-b-[3px] border-r-[3px] border-white"></div>

                        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-4 h-4 opacity-70 flex items-center justify-center">
                            <div className="w-full h-[2px] bg-white absolute"></div>
                            <div className="h-full w-[2px] bg-white absolute"></div>
                        </div>
                    </div>
                </div>

                {rawViewportShot && (
                  <div className="absolute bottom-4 right-4 md:bottom-6 md:right-6 z-30 w-32 md:w-48 bg-[#111] border border-[#222] pt-1 pb-2 px-2 shadow-2xl opacity-60 hover:opacity-100 transition-opacity pointer-events-auto">
                    <div className="flex justify-between items-center mb-1">
                      <span className="block text-[9px] text-[#666] uppercase tracking-widest pl-1">Last Capture</span>
                      <button onClick={() => setRawViewportShot(null)} className="text-[#666] hover:text-white px-2 cursor-pointer">✕</button>
                    </div>
                    <img src={rawViewportShot} className="w-full aspect-video object-cover border border-[#222] cursor-zoom-in" onClick={() => setLightboxImage(rawViewportShot)} />
                  </div>
                )}

                {/* Mini Map */}
                <div className="absolute bottom-4 left-4 md:bottom-6 md:left-6 z-30 w-32 md:w-56 bg-[#111] border border-[#222] p-2 shadow-2xl transition-opacity pointer-events-auto">
                  <div 
                    className="relative w-full aspect-[2/1] border border-[#222] bg-[#111] overflow-hidden cursor-zoom-in" 
                    onClick={() => panoramaUrl && setLightboxImage(panoramaUrl)}
                  >
                    {panoramaUrl && (
                      <img src={panoramaUrl} alt="Equirectangular Map" className="absolute inset-0 w-full h-full object-cover opacity-80" />
                    )}
                    <MiniMapOverlay yaw={viewState.yaw} pitch={viewState.pitch} fov={viewState.fov} />
                  </div>
                </div>

                <div className="absolute bottom-6 md:bottom-12 left-0 right-0 flex justify-center z-10 pointer-events-none">
                  <button 
                    onClick={handleRenderShot}
                    disabled={isRenderingShot || !panoramaUrl}
                    className="pointer-events-auto bg-[#111]/60 backdrop-blur-md border border-white hover:bg-white text-white hover:text-black disabled:opacity-30 disabled:hover:bg-[#111]/60 disabled:hover:text-white px-8 md:px-10 py-3.5 md:py-4 rounded-full font-normal text-[10px] md:text-[11px] uppercase tracking-[0.15em] flex items-center gap-3 transition-colors group"
                  >
                    {isRenderingShot ? <Loader2 className="w-4 h-4 animate-spin" /> : <Camera className="w-5 h-5" />}
                    {isRenderingShot ? 'Capturing...' : 'Capture & Enhance'}
                  </button>
                </div>
            </div>
          </div>

          <div className="w-full md:w-[340px] h-[35vh] md:h-full shrink-0 bg-[#111] border-t md:border-t-0 md:border-l border-[#222] flex flex-col z-20 order-2 md:order-none">
            <div className="p-4 md:p-8 border-b border-[#222] flex items-center justify-between shrink-0">
                <div className="text-sm font-normal tracking-wide text-white">
                    SCOUTER<span className="text-[#666]">360</span>
                </div>
                <div className="flex items-center gap-3 md:gap-4">
                    <select 
                      value={numEnhancements} 
