      {(lightboxImage || lightboxIndex !== null) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/95 p-4 md:p-8 backdrop-blur-md transition-all">
          {lightboxIndex !== null && savedShots[lightboxIndex] && savedShots[lightboxIndex].base64 ? (
             <div className="relative w-full h-full flex flex-col items-center justify-center">
                <button 
                  className="absolute top-4 right-4 bg-transparent border border-[#333] hover:border-white text-[#eee] w-10 h-10 flex items-center justify-center transition-colors font-bold z-50"
