                >
                  ✕
                </button>
                <div className="flex items-center justify-center w-full h-full gap-4 md:gap-8 max-h-[85vh]">
                  <button 
                    className="flex-shrink-0 bg-transparent border border-[#222] hover:border-white p-3 md:p-4 text-[#eee] disabled:opacity-30 transition-all outline-none hidden sm:block"
                    onClick={() => setLightboxIndex(prev => prev !== null ? prev - 1 : prev)}
                    disabled={lightboxIndex === 0}
                  >
                    <ChevronLeft className="w-6 h-6" />
                  </button>

                  <div className="relative max-h-full flex flex-col max-w-full">
                    <img 
                      src={savedShots[lightboxIndex].base64!} 
                      alt="Expanded view" 
                      className="max-h-[70vh] md:max-h-[80vh] max-w-full w-auto border border-[#222] object-contain mx-auto" 
                    />
                    <div className="absolute -bottom-12 md:-bottom-14 left-0 right-0 flex justify-end text-white">
                      <button 
                        onClick={() => downloadImage(savedShots[lightboxIndex].base64 as string, lightboxIndex)}
                        className="flex items-center gap-2 md:gap-3 border border-[#333] hover:border-white hover:text-white text-[#aaa] bg-[#111] px-4 md:px-6 py-2.5 md:py-3 text-[9px] md:text-[10px] uppercase tracking-[0.1em] transition-colors"
                      >
                        <Download className="w-4 h-4" />
                        Download
                      </button>
                    </div>
                  </div>

                  <button 
                    className="flex-shrink-0 bg-transparent border border-[#222] hover:border-white p-3 md:p-4 text-[#eee] disabled:opacity-30 transition-all outline-none hidden sm:block"
                    onClick={() => setLightboxIndex(prev => prev !== null ? prev + 1 : prev)}
                    disabled={lightboxIndex === savedShots.length - 1}
                  >
                    <ChevronRight className="w-6 h-6" />
                  </button>
                </div>
             </div>
          ) : lightboxImage ? (
             <div className="relative w-full h-full flex items-center justify-center">
                <button 
                  className="absolute top-4 right-4 bg-transparent border border-[#333] hover:border-white text-[#eee] w-10 h-10 flex items-center justify-center transition-colors font-bold z-50"
                  onClick={() => setLightboxImage(null)}
                >
                  ✕
                </button>
                <img src={lightboxImage} alt="Expanded view" className="max-w-[95vw] max-h-[85vh] object-contain border border-[#222]" />
             </div>
          ) : null}
        </div>
      )}
    </div>
  );
}

import { forwardRef, useImperativeHandle, useRef, useEffect, Suspense } from 'react';
import { Canvas, useThree } from '@react-three/fiber';
import { OrbitControls, useTexture } from '@react-three/drei';
import * as THREE from 'three';
import { Loader2 } from 'lucide-react';

interface SceneProps {
  imageUrl: string;
  onViewChange?: (yaw: number, pitch: number, fov: number) => void;
}

export interface SceneRef {
  renderFrame: () => void;
}

const WebGLScene = forwardRef<SceneRef, SceneProps>(({ imageUrl, onViewChange }, ref) => {
  const texture = useTexture(imageUrl);
  const { gl, scene, camera } = useThree();
  const controlsRef = useRef<any>(null);

  const reportViewChange = () => {
    if (controlsRef.current && onViewChange) {
      const yaw = controlsRef.current.getAzimuthalAngle();
      const pitch = controlsRef.current.getPolarAngle();
      const cam = camera as THREE.PerspectiveCamera;
      onViewChange(yaw, pitch, cam.fov);
    }
  };

  useImperativeHandle(ref, () => ({
    renderFrame: () => {
      gl.render(scene, camera);
    }
  }));

  useEffect(() => {
    if (texture) {
      // By default the sphere geometry expects a 2:1 image bounds mapping, but we are injecting a 16:9 
      // image. Let's allow the texture wrapping to adjust smoothly without hard black borders.
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.needsUpdate = true;
    }
  }, [texture]);

  useEffect(() => {
    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      const cam = camera as THREE.PerspectiveCamera;
      cam.fov = Math.max(10, Math.min(120, cam.fov + (e.deltaY * 0.05)));
      cam.updateProjectionMatrix();
      reportViewChange();
    };
    const domElement = gl.domElement;
    domElement.addEventListener('wheel', handleWheel, { passive: false });
    return () => domElement.removeEventListener('wheel', handleWheel);
  }, [camera, gl]);

  // Initial report
  useEffect(() => {
    if (controlsRef.current) {
      reportViewChange();
    }
  }, []);

  return (
    <>
      <OrbitControls
        ref={controlsRef}
        enableZoom={false}
        enablePan={false}
        rotateSpeed={0.5} 
        target={[0, 0, 0]}
        onChange={reportViewChange}
      />

      <mesh scale={[-1, 1, 1]}>
        <sphereGeometry args={[500, 60, 40]} />
        <meshBasicMaterial map={texture} side={THREE.DoubleSide} />
      </mesh>
    </>
  );
});

export interface PanoramaViewerRef {
  capture: () => string | null;
}

interface PanoramaViewerProps {
  imageUrl: string;
  onViewChange?: (yaw: number, pitch: number, fov: number) => void;
}

export const PanoramaViewer = forwardRef<PanoramaViewerRef, PanoramaViewerProps>(
  ({ imageUrl, onViewChange }, ref) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const sceneRef = useRef<SceneRef>(null);

    useImperativeHandle(ref, () => ({
      capture: () => {
        if (!canvasRef.current || !sceneRef.current) return null;
        // Render forcing a draw call synchronously before extracting the canvas
        sceneRef.current.renderFrame();

        const sourceCanvas = canvasRef.current;
        const viewfinder = document.getElementById('viewfinder');
        const canvasRect = sourceCanvas.getBoundingClientRect();

        let cropX = 0;
        let cropY = 0;
        let cropWidth = sourceCanvas.width;
        let cropHeight = sourceCanvas.height;

        if (viewfinder && canvasRect.width > 0 && canvasRect.height > 0) {
          const vfRect = viewfinder.getBoundingClientRect();
          const scaleX = sourceCanvas.width / canvasRect.width;
          const scaleY = sourceCanvas.height / canvasRect.height;

          cropX = (vfRect.left - canvasRect.left) * scaleX;
          cropY = (vfRect.top - canvasRect.top) * scaleY;
          cropWidth = vfRect.width * scaleX;
          cropHeight = vfRect.height * scaleY;
        } else {
          const targetAspectRatio = 16 / 9;

          if (sourceCanvas.width / sourceCanvas.height > targetAspectRatio) {
            // Canvas is wider than 16:9, so height is the bottleneck
            cropWidth = sourceCanvas.height * targetAspectRatio;
          } else {
            // Canvas is taller than 16:9 or exactly 16:9, so width is the bottleneck
            cropHeight = sourceCanvas.width / targetAspectRatio;
          }

          cropX = (sourceCanvas.width - cropWidth) / 2;
          cropY = (sourceCanvas.height - cropHeight) / 2;
        }

        const Math_max = Math.max;
        const Math_min = Math.min;
        const Math_round = Math.round;

        const MAX_WIDTH = 1280;
        const scale = Math_min(1, MAX_WIDTH / cropWidth);
        const finalWidth = Math_round(cropWidth * scale);
        const finalHeight = Math_round(cropHeight * scale);

        const outputCanvas = document.createElement('canvas');
        outputCanvas.width = finalWidth;
        outputCanvas.height = finalHeight;
        const ctx = outputCanvas.getContext('2d');
        if (!ctx) return null;

        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';

        ctx.drawImage(
          sourceCanvas,
          Math_max(0, cropX), Math_max(0, cropY), cropWidth, cropHeight,
          0, 0, finalWidth, finalHeight
        );

        return outputCanvas.toDataURL('image/jpeg', 0.9);
      }
    }));

    return (
      <div className="absolute inset-0 cursor-move bg-transparent">
        <Canvas
          ref={canvasRef}
          camera={{ position: [0, 0, 0.1], fov: 70 }}
          gl={{ preserveDrawingBuffer: true, powerPreference: "high-performance" }}
        >
          <Suspense fallback={null}>
            <WebGLScene ref={sceneRef} imageUrl={imageUrl} onViewChange={onViewChange} />
          </Suspense>
        </Canvas>
      </div>
    );
  }
);

import { Flow } from "flow-sdk";

export async function analyzeSpace(imageBase64: string, briefInfo: string): Promise<string> {
  const mimeTypeMatch = imageBase64.match(/^data:(image\/[a-zA-Z]+);base64,/);
  const mimeType = mimeTypeMatch ? mimeTypeMatch[1] : "image/jpeg";
  const base64Data = imageBase64.replace(/^data:image\/[a-zA-Z]+;base64,/, "");

  const prompt = `You are an expert architectural prompt engineer. The user wants to expand the provided reference image ('${briefInfo}') into a full 360-degree environment. The provided image represents the FRONT view of the space. 

Analyze the image and extrapolate what exists outside the frame seamlessly. Do not reinterpret the front view, focus entirely on generating detailed descriptions for the missing parts of the room.

Structure your response EXACTLY like this:
STYLE & LIGHTING: [Overall architectural style, materials, and lighting atmosphere]
LEFT: [Detailed description of the left side]
RIGHT: [Detailed description of the right side]
BACK: [Detailed description of the area behind the camera]
CEILING: [Detailed description of the ceiling/sky]
FLOOR: [Detailed description of the floor/ground]`;

  const { text } = await Flow.generate.text(prompt, {
    images: [{ base64: base64Data, mimeType: mimeType }],
  });

  return text || "";
}

export async function generate360(globalContext: string, imageBase64: string): Promise<string> {
  const mimeTypeMatch = imageBase64.match(/^data:(image\/[a-zA-Z]+);base64,/);
  const mimeType = (mimeTypeMatch ? mimeTypeMatch[1] : "image/jpeg") as 'image/png' | 'image/jpeg';
  const base64Data = imageBase64.replace(/^data:image\/[a-zA-Z]+;base64,/, "");

  // Use Flow.upload to get a mediaId for generation
  const { mediaId } = await (Flow as any).upload({
    base64: base64Data,
    mimeType: mimeType,
    name: 'Reference Frame'
  });

  const prompt = `Equirectangular 360 panorama projection format. Incorporate the provided reference image clearly as the FRONT view of the environment. While the core essence, colors, subject matter, and layout of the reference image must be strongly preserved, you are allowed to naturally adapt its distortion, perspective, and edges to properly fit a true equirectangular 360 projection format.

Expand this space into a complete 360 environment (left, right, back, top, bottom) surrounding the front view, guided by the following additional instructions:

${globalContext}

Ensure a complete, seamless 360-degree room with continuous lighting and cohesive architectural geometry. It is highly critical that the final output possesses the warped perspective characteristics of an equirectangular projection so it seamlessly wraps onto a 3D sphere.`;

  const result = await Flow.generate.image({
    prompt: prompt,
    referenceImageMediaIds: [mediaId],
    aspectRatio: "16:9",
    modelDisplayName: "Nano Banana Pro"
  });

  return `data:${result.mimeType};base64,${result.base64}`;
}

export async function enhanceCleanShot(canvasBase64: string, instruction: string): Promise<string> {
  const mimeTypeMatch = canvasBase64.match(/^data:(image\/[a-zA-Z]+);base64,/);
  const mimeType = (mimeTypeMatch ? mimeTypeMatch[1] : "image/jpeg") as 'image/png' | 'image/jpeg';
  const base64Data = canvasBase64.replace(/^data:image\/[a-zA-Z]+;base64,/, "");

  // Use Flow.upload to get a mediaId for enhancement
  const { mediaId } = await (Flow as any).upload({
    base64: base64Data,
    mimeType: mimeType,
    name: 'Viewport Capture'
  });

  const prompt = `${instruction} High quality, clean up the warping and stretching artefacts from spherical projection. Keep the style the same as the original image.`;

  const result = await Flow.generate.image({
    prompt: prompt,
    referenceImageMediaIds: [mediaId],
    aspectRatio: "16:9",
    modelDisplayName: "Nano Banana Pro"
  });

  return `data:${result.mimeType};base64,${result.base64}`;
}
